package com.portfolio.service;
import com.portfolio.entity.*; import com.portfolio.repository.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@Service public class ImageService {private final ImageRepository repo;private final CategoryRepository cats;private final FileStorageService files; public ImageService(ImageRepository r,CategoryRepository c,FileStorageService f){repo=r;cats=c;files=f;} public List<Image> publicAll(){return repo.findByVisibleTrueOrderByDisplayOrderAscCreatedAtDesc();} public List<Image> adminAll(){return repo.findAllByOrderByDisplayOrderAscCreatedAtDesc();} public Image get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Image not found"));}
 public Image create(String title,String description,Long categoryId,Integer order,Boolean visible,MultipartFile file){if(title==null||title.isBlank())throw new IllegalArgumentException("Title is required");Image x=new Image();x.setTitle(title);x.setDescription(description);x.setImageUrl(files.save(file,"images"));x.setDisplayOrder(order==null?0:order);x.setVisible(visible==null||visible);if(categoryId!=null)x.setCategory(cats.findById(categoryId).orElseThrow(()->new NoSuchElementException("Category not found")));return repo.save(x);}
 public Image update(Long id,String title,String description,Long categoryId,Integer order,Boolean visible,MultipartFile file){Image x=get(id);if(title!=null&&!title.isBlank())x.setTitle(title);x.setDescription(description);if(categoryId!=null)x.setCategory(cats.findById(categoryId).orElseThrow(()->new NoSuchElementException("Category not found")));if(order!=null)x.setDisplayOrder(order);if(visible!=null)x.setVisible(visible);if(file!=null&&!file.isEmpty()){files.deleteByUrl(x.getImageUrl());x.setImageUrl(files.save(file,"images"));}x.touch();return repo.save(x);}
 public void delete(Long id){Image x=get(id);files.deleteByUrl(x.getImageUrl());repo.delete(x);}}
